import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type NotificationCascadeProps = Record<string, any>;

const NotificationCascade: React.FC<NotificationCascadeProps> = ({
  backgroundColor = "#0d1117",
  transparentBackground = false,
  durationInSeconds = 5,
  messages = [
    "Build is failing",
    "Looking into it",
    "Blocked on data team",
    "Getting alerts",
  ],
  bubbleColor = "#21262d",
  textColor = "#c9d1d9",
  glowColor = "#da3633",
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const staggerFrames = 12;

  // Stress indicator builds up significantly after the second message appears
  const stressStartFrame = staggerFrames * 1.5;
  const stressEndFrame = staggerFrames * 3.5;

  const stressLevel = interpolate(
    frame,
    [stressStartFrame, stressEndFrame],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // Add a subtle throb to the glow when fully stressed
  const pulse = Math.sin(frame * 0.15) * 0.5 + 0.5;
  const currentGlowMultipler = stressLevel * (0.7 + pulse * 0.3);

  // Shake effect scales with stress level
  const shakeX = Math.sin(frame * 0.8) * stressLevel * 6;
  const shakeY = Math.cos(frame * 1.3) * stressLevel * 4;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 24,
          padding: 48,
          borderRadius: 32,
          width: width * 0.45,
          transform: `translate(${shakeX}px, ${shakeY}px)`,
          boxShadow: `0 0 ${currentGlowMultipler * 120}px ${glowColor}60, inset 0 0 ${currentGlowMultipler * 60}px ${glowColor}30`,
          border: `${stressLevel * 3}px solid ${glowColor}`,
          backgroundColor: `rgba(0, 0, 0, ${stressLevel * 0.6})`,
          transition: "none",
        }}
      >
        {messages.map((msg, i) => {
          const delay = i * staggerFrames;
          const entrance = spring({
            frame: frame - delay,
            fps,
            config: { damping: 12, stiffness: 150, mass: 0.8 },
          });

          const itemY = interpolate(entrance, [0, 1], [60, 0]);
          const itemScale = interpolate(entrance, [0, 1], [0.85, 1]);
          const itemOpacity = interpolate(entrance, [0, 1], [0, 1]);

          return (
            <div
              key={i}
              style={{
                display: "flex",
                alignItems: "center",
                backgroundColor: bubbleColor,
                padding: "24px 32px",
                borderRadius: 20,
                gap: 24,
                opacity: itemOpacity,
                transform: `translateY(${itemY}px) scale(${itemScale})`,
                boxShadow: "0 15px 35px rgba(0,0,0,0.4)",
                border: "1px solid rgba(255,255,255,0.05)",
                transition: "none",
              }}
            >
              {/* Generic Avatar Placeholder */}
              <div
                style={{
                  width: 56,
                  height: 56,
                  borderRadius: "50%",
                  backgroundColor: "rgba(255, 255, 255, 0.08)",
                  flexShrink: 0,
                }}
              />
              <div
                style={{
                  color: textColor,
                  fontSize: 36,
                  fontWeight: 500,
                  lineHeight: 1.3,
                  letterSpacing: "-0.02em",
                }}
              >
                {msg}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default NotificationCascade;